import os, shutil, re, json, argparse

# Arguments passed to this script from CMake
parser = argparse.ArgumentParser(description="Post-build/install packaging for the Bifrost pack")
parser.add_argument("--build-folder", help="Build folder name, relative to the project root")
parser.add_argument("--pack-name", help="Pack name")
parser.add_argument("--pack-version", help="Pack version")
args = parser.parse_args()


# Folder containing this script (this should be the project's root folder)
ROOT_FOLDER = os.path.dirname(__file__).replace("\\", "/")
# Pack generated by the build process, this will only contain operators
BUILT_PACK_FOLDER = f"{ROOT_FOLDER}/{args.build_folder}/{args.pack_name}-{args.pack_version}"
# Existing complete pack with operactors/compounds/graphs/etc.
DST_PACK_FOLDER = f"{ROOT_FOLDER}/packs/{args.pack_name}"
print("dst pack folder:", DST_PACK_FOLDER)

# Copy newly built ops to /packs, ignoring unnecessary folders
IGNORED_FOLDERS = {"bin", "lib/pkgconfig"}
def ignore_folders(directory, names):
    rel_dir = os.path.relpath(directory, BUILT_PACK_FOLDER).replace("\\", "/")
    return [name for name in names if (name if rel_dir == "." else f"{rel_dir}/{name}") in IGNORED_FOLDERS]
shutil.copytree(BUILT_PACK_FOLDER, DST_PACK_FOLDER, dirs_exist_ok=True, ignore=ignore_folders)


# Set name display mode for set_kernel_arg nodes.
OPEN_CL_JSON = f"{DST_PACK_FOLDER}/lib/OpenCL.json"
with open(OPEN_CL_JSON, "r") as f:
    data = json.load(f)

for operator in data["operators"]:
    if operator["name"] != "Hyuu::OpenCL::Execute::set_kernel_arg":
        continue
    metadata = operator.setdefault("metadata", [])
    metadata.append({
        "metaName": "NodeValueDisplay",
        "metadata": [
            {
                "metaName": "show",
                "metaType": "string",
                "metaValue": "1"
            },
            {
                "metaName": "format",
                "metaType": "string",
                "metaValue": "Set Kernel Arg {arg_id}"
            }
        ]
    })

with open(OPEN_CL_JSON, "w") as f:
    json.dump(data, f, indent=4)